  async function refresh() {
    if (state.busy) return;
    state.busy = true;
    try { setCrew(await request('station-room')); pollTrades(); }
    catch (error) { if (state.inside) status(error.message); }
    finally { state.busy = false; }
  }
  async function dockAndEnter(body) {
    if (!body || !Array.isArray(window.stationIds)||!window.stationIds.includes(body.id) || state.docking) return;
    state.docking = true;
    window.dockingRequested = true;
    try {
      status('Confirmando acoplamento...');
      const result = await request('station-dock', {station: body.id}, '', 8000);
      const cinematic = window.dockingCinematic?.start(body);
      await cinematic;
      window.dockingCinematic?.finish();
      window.gameAudio?.play('dock');
      window.crewDocked = true; document.body.classList.add('station-docked-mode');
      state.forceInterior=true; show(); status('Acoplagem confirmada. Abrindo a sala de convivência...');
      await refresh();
      if(!state.inside) throw new Error('A nave acoplou, mas a sala não carregou. Clique em ATUALIZAR dentro da sala ou tente entrar novamente.');
      status('Nave guardada em ' + result.station + '. Convide um piloto para ocupar a cadeira de copiloto.');
    } catch (error) {
      await window.dockingCinematic?.cancel(); state.forceInterior=false; if(!state.inside)hide();
      const message=error.message||'Não foi possível acoplar a nave.';
      status(message);
      const dockStatus=document.querySelector('#dockStatus'),routeStatus=document.querySelector('#routeStatus'),toast=document.querySelector('#toast');
      if(dockStatus)dockStatus.textContent=message;
      if(routeStatus)routeStatus.textContent=message;
      if(toast){toast.textContent=message;toast.style.cssText+=';z-index:210;max-width:calc(100vw - 28px);padding:10px 12px;border:1px solid #65dbe788;border-radius:5px;background:#061521ed;line-height:1.45;text-align:center';toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),5000)}
    }
    finally { window.dockingRequested = false; state.docking = false; }
  }
  async function undockForOrbit() {
    if (!window.crewDocked) return;
    if (window.crewRole === 'copilot' || window.crewRole === 'passenger') throw new Error('Somente o piloto pode desacoplar a nave.');
    if (!window.crewCanUndock) throw new Error('Somente o piloto pode desacoplar a nave.');
    await request('station-undock', {});
    window.crewDocked=false;window.crewCanUndock=false;document.body.classList.remove('station-docked-mode');
    state.inside=false;state.station=null;state.forceInterior=false;badge.hidden=true;hide();
    await game.refreshShip();await refresh();
  }
  async function attackSelectedStation(body) {
    if (!body || !Array.isArray(window.stationIds)||!window.stationIds.includes(body.id)) return;
    const button = document.querySelector('#stationAttackButton');
    if (button) { button.disabled = true; button.textContent = 'DISPARANDO...'; }
    try {
      const result = await game.attackStation(body.id);
      window.gameAudio?.play(result.destroyed ? 'explosion' : 'impact', {force:true});
      if (button) button.textContent = result.destroyed ? 'ESTACAO DESATIVADA' : 'IMPACTO / ' + result.damage + ' DMG / CASCO ' + result.hull;
      setTimeout(() => { if (button) button.textContent = 'ATACAR ESTACAO'; }, 1800);
    } catch (error) {
      const node = document.querySelector('#dockStatus'); if (node) node.textContent = error.message;
      if (button) button.textContent = 'ATACAR ESTACAO';
    }
  }
